refentry.refsect1:
  &reftitle.examples;



    Esempi di list


<?php

$info = array('caffè', 'marrone', 'caffeina');

// Elencare tutte le variabili
list($drink, $color, $power) = $info;
echo "Il $drink è $color e la $power lo rende speciale.\n";

// Elencarne solo alcune
list($drink, , $power) = $info;
echo "Il $drink contiene $power.\n";

// Oppure passare direttamente alla terza
list( , , $power) = $info;
echo "Ho bisogno di $power!\n";

// list() non funziona con le stringhe
list($bar) = "abcde";
var_dump($bar); // NULL
?>







    Esempio di utilizzo di list


<?php
$result = $pdo->query("SELECT id, name FROM employees");
while (list($id, $name) = $result->fetch(PDO::FETCH_NUM)) {
    echo "id: $id, name: $name\n";
}
?>







    Uso di list annidati


<?php

list($a, list($b, $c)) = array(1, array(2, 3));

var_dump($a, $b, $c);

?>


    &example.outputs;


int(1)
int(2)
int(3)






   L'ordine in cui sono definiti gli indici dell'array che deve essere usato da
   list è irrilevante.




    list e ordine di definizione degli indici


<?php
$foo = array(2 => 'a', 'foo' => 'b', 0 => 'c');
$foo[1] = 'd';
list($x, $y, $z) = $foo;
var_dump($foo, $x, $y, $z);




     Produce il seguente output (si noti l'ordine degli elementi rispetto
     all'ordine in cui sono stati scritti nella sintassi di list):



array(4) {
  [2]=>
  string(1) "a"
  ["foo"]=>
  string(1) "b"
  [0]=>
  string(1) "c"
  [1]=>
  string(1) "d"
}
string(1) "c"
string(1) "d"
string(1) "a"







    list con chiavi

     A partire da PHP 7.1.0, list può contenere anche
     chiavi esplicite, che possono essere espressioni arbitrarie.
     È consentito combinare chiavi intere e stringa; tuttavia, gli elementi
     con e senza chiave non possono essere combinati.



<?php
$data = [
    ["id" => 1, "name" => 'Tom'],
    ["id" => 2, "name" => 'Fred'],
];
foreach ($data as ["id" => $id, "name" => $name]) {
    echo "id: $id, name: $name\n";
}
echo PHP_EOL;
list(1 => $second, 3 => $fourth) = [1, 2, 3, 4];
echo "$second, $fourth\n";


    &example.outputs;


id: 1, name: Tom
id: 2, name: Fred

2, 4
